<h4 class="fw-bold mb-4">Minhas pendências</h4><div class="card"><table class="table mb-0"><thead><tr><th>Solicitação</th><th>Tipo</th><th>Prazo</th><th>Status</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?= htmlspecialchars($r['title'] ?? '') ?><div class="text-muted small"><?= htmlspecialchars($r['description'] ?? '') ?></div></td><td><?= htmlspecialchars($r['request_type'] ?? '') ?></td><td><?= htmlspecialchars($r['due_date'] ?? '') ?></td><td><?= htmlspecialchars($r['status'] ?? '') ?></td></tr><?php endforeach; ?><?php if(empty($requests)): ?><tr><td colspan="4" class="text-center text-muted p-4">Nenhuma pendência.</td></tr><?php endif; ?></tbody></table></div>